<!DOCTYPE html>
<html lang="en">

<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>User Tickets</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            padding: 0;
        }

        .ticket-page {
            page-break-after: always;
            height: 100vh;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
        }

        .qr-code {
            margin-bottom: 20px;
        }

        h2 {
            margin-bottom: 10px;
        }
    </style>
</head>

<body>
    <div id="ticket-content">
        @foreach ($user->tickets as $ticket)
            @if ($ticket->orderHasPaid())
                <div class="ticket-page">
                    <h2>{{ $ticket->activity->name }}</h2>
                    <p>Ticket Code: {{ $ticket->code }}</p>
                    <div class="qr-code" id="qr-code-{{ $ticket->id }}"></div>
                    <p>{{ $user->name }}</p>
                </div>
            @endif
        @endforeach
    </div>

    <script type="text/javascript" src="https://unpkg.com/qr-code-styling@1.5.0/lib/qr-code-styling.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"
        integrity="sha512-GsLlZN/3F2ErC5ifS5QtgpiJtWd43JWSuIgh7mbzZ8zBps+dvLusV+eNQATqgA/HdeKFVgA5v3S/cIrLF7QnIg=="
        crossorigin="anonymous" referrerpolicy="no-referrer"></script>
    </script>

    <script type="text/javascript">
        let imageLogoBase64 =
            "data:image/webp;base64,"

        @foreach ($user->tickets as $ticket)
            @if ($ticket->orderHasPaid())
                const qrCode{{ $ticket->id }} = new QRCodeStyling({
                    width: 300,
                    height: 300,
                    type: "svg",
                    data: "{{ $ticket->code }}",
                    image: imageLogoBase64,
                    imageOptions: {
                        margin: 5
                    }
                });
                qrCode{{ $ticket->id }}.append(document.getElementById("qr-code-{{ $ticket->id }}"));
            @endif
        @endforeach

        function generatePDF() {
            const element = document.getElementById('ticket-content');
            html2pdf()
                .from(element)
                .save()
                .then(function() {
                    window.location.href = "{{ route('global.home') }}";
                });
        }

        document.addEventListener('DOMContentLoaded', function() {
            generatePDF();
        });
    </script>
</body>

</html>
